    void saveInterval(EditText field){int seconds;try{seconds=Integer.parseInt(field.getText().toString().trim());}catch(Exception e){throw new IllegalArgumentException("Укажите интервал целым числом: от 0 до 3600 секунд");}if(seconds<0||seconds>3600)throw new IllegalArgumentException("Интервал может быть от 0 до 3600 секунд");Store.set("delay",Integer.toString(seconds));}
