        BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int i){return visible.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){JSONObject c=visible.get(i);LinearLayout row=column();row.setPadding(dp(12),dp(8),dp(12),dp(8));row.setMinimumHeight(dp(76));TextView name=text(c.optString("name").isEmpty()?Store.contactIdentity(c):c.optString("name"),16,ink);name.setTypeface(null,Typeface.BOLD);row.addView(name);row.addView(text(Store.contactIdentity(c)+" · "+c.optString("group"),13,muted));return row;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,i,id)->contactDetails(visible.get(i)));
        Runnable update=()->{visible.clear();String q=search.getText().toString().toLowerCase(Locale.ROOT),g=filter.getSelectedItemPosition()==0?"":filter.getSelectedItem().toString();JSONArray all=Store.list("contacts");for(int i=0;i<all.length();i++){JSONObject c=all.optJSONObject(i);if((g.isEmpty()||g.equals(c.optString("group")))&&(c.toString().toLowerCase(Locale.ROOT).contains(q)))visible.add(c);}adapter.notifyDataSetChanged();};
