        ListView list=new ListView(this);list.setDivider(null);body.addView(list,new LinearLayout.LayoutParams(-1,dp(400)));BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int i){return visible.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){PhoneContacts.Contact c=visible.get(i);CheckBox box=new CheckBox(MainActivity.this);tintCheck(box);box.setText((c.name.isEmpty()?"Без имени":c.name)+"\n"+c.phone);box.setTextColor(ink);box.setTextSize(15);box.setMinHeight(dp(68));box.setChecked(selected.contains(c.phone));box.setOnCheckedChangeListener((v,checked)->{if(checked)selected.add(c.phone);else selected.remove(c.phone);counter.setText("Выбрано: "+selected.size()+" из "+all.size());});return box;}};list.setAdapter(adapter);
