        sticky(button("Добавить выбранные",()->{String g=group.getText().toString().trim();if(g.isEmpty()||selected.isEmpty())throw new IllegalArgumentException("Укажите список и выберите контакты");int added=0;for(PhoneContacts.Contact c:all)if(selected.contains(c.phone)&&Store.addContact(Store.object("phone",c.phone,"name",c.name,"group",g,"fields",new JSONObject())))added++;Store.save();draftGroup=g;show(1);info("Добавлено: "+added+". Повторы в списке пропущены.");},true));
