    void mapping(List<List<String>> rows,String suggested){
        shell("Настроить импорт",true);beginPanel("Проверим таблицу","Выберите, что находится в нужных колонках.");if(rows.isEmpty())throw new IllegalArgumentException("Файл пуст");
        CheckBox header=new CheckBox(this);tintCheck(header);header.setText("Первая строка — названия колонок");header.setTextColor(ink);header.setMinHeight(dp(48));header.setChecked(!Core.cell(rows.get(0),0).trim().matches("[+0-9() .\\-]+"));body.addView(header);
        List<String> cols=new ArrayList<>();int max=0;for(List<String> r:rows)max=Math.max(max,r.size());for(int i=0;i<max;i++)cols.add((i+1)+": "+Core.cell(rows.get(0),i));
        label("Тип адреса");final String[] importKinds={"whatsapp_app","telegram_web","max_web","telegram_bot","max_bot"};Spinner addressType=spinner(Arrays.asList("Телефон WhatsApp","Telegram — личный адрес","MAX — личный адрес","Telegram — Chat ID бота","MAX — chat:ID или user:ID"),0);label("Колонка с адресом");int phone=0,name=-1;for(int i=0;i<rows.get(0).size();i++){String h=rows.get(0).get(i).toLowerCase(Locale.ROOT);if(h.matches(".*(phone|номер|телефон|mobile).*"))phone=i;if(h.matches(".*(name|имя|фио).*"))name=i;}
        Spinner ps=spinner(cols,phone);addressType.setOnItemSelectedListener(new SimpleSelected(){public void onItemSelected(AdapterView<?> parent,View view,int pos,long id){String key=Channels.key(importKinds[pos]);for(int col=0;col<rows.get(0).size();col++)if(rows.get(0).get(col).equalsIgnoreCase(key))ps.setSelection(col);}});label("Колонка с именем");List<String> nc=new ArrayList<>();nc.add("Без имени");nc.addAll(cols);Spinner ns=spinner(nc,name+1);
        label("Код страны для местных номеров");EditText country=edit("7",Store.setting("country","7"),false);country.setInputType(3);label("Сохранить в группу");EditText group=edit("Название группы",suggested,false);
        note("Первые строки:");for(int i=0;i<Math.min(4,rows.size());i++)note(android.text.TextUtils.join(" · ",rows.get(i)));
        sticky(button("Проверить импорт",()->{
            String g=group.getText().toString().trim(),cc=country.getText().toString().replaceAll("[^0-9]","");if(g.isEmpty()||cc.isEmpty())throw new IllegalArgumentException("Укажите группу и код страны");
            List<JSONObject> accepted=new ArrayList<>();List<String> errors=new ArrayList<>();Set<String> seen=new HashSet<>();int duplicates=0;List<String> keys=new ArrayList<>();
            for(int i=0;i<cols.size();i++){String k=header.isChecked()?Core.cell(rows.get(0),i).trim().replace("{","").replace("}",""):"column"+(i+1);if(k.isEmpty())k="column"+(i+1);String original=k;int suffix=2;while(keys.contains(k))k=original+"_"+(suffix++);keys.add(k);}
            for(int i=header.isChecked()?1:0;i<rows.size();i++){try{List<String> r=rows.get(i);String importChannel=importKinds[addressType.getSelectedItemPosition()];String rawAddress=Core.cell(r,ps.getSelectedItemPosition());String address=importChannel.equals("whatsapp_app")?Core.phone(rawAddress,cc):Channels.normalize(importChannel,rawAddress);String p=importChannel.equals("whatsapp_app")?address:"";if(!seen.add(address)){duplicates++;continue;}JSONObject f=new JSONObject();for(int j=0;j<keys.size();j++)Store.put(f,keys.get(j),Core.cell(r,j));int embedded=keys.indexOf("fields_json");if(embedded>=0&&!Core.cell(r,embedded).isEmpty()){JSONObject extra=new JSONObject(Core.cell(r,embedded));Iterator<String> extraKeys=extra.keys();while(extraKeys.hasNext()){String k=extraKeys.next();if(!f.has(k))Store.put(f,k,extra.optString(k));}}Store.put(f,Channels.key(importChannel),address);accepted.add(Store.object("phone",p,"name",Core.cell(r,ns.getSelectedItemPosition()-1),"group",g,"fields",f));}catch(Exception ex){if(errors.size()<30)errors.add("Строка "+(i+1)+": "+ex.getMessage());}}
            if(accepted.isEmpty())throw new IllegalArgumentException("Нет корректных номеров.\n"+android.text.TextUtils.join("\n",errors));
            final int dup=duplicates;shell("Проверка импорта",true);beginPanel("Всё готово к добавлению","");label("К сохранению: "+accepted.size());note("Группа: "+g+" · повторы внутри файла: "+dup);note("Подстановки: {name}, {phone}, "+android.text.TextUtils.join(", ",keys));for(int i=0;i<Math.min(5,accepted.size());i++)note(accepted.get(i).optString("name")+" · "+Store.contactIdentity(accepted.get(i)));if(!errors.isEmpty())note("Некорректные строки не будут добавлены (первые 30):\n"+android.text.TextUtils.join("\n",errors));
            sticky(button("Сохранить контакты",()->{int added=0;for(JSONObject c:accepted)if(Store.addContact(c))added++;Store.save();Store.set("country",cc);draftGroup=g;show(1);info("Добавлено: "+added+". Уже в группе: "+(accepted.size()-added)+".");},true));
        },true));
    }
    void history(){JSONArray queues=Store.list("campaigns");if(queues.length()==0){beginPanel("Пока здесь пусто","После проверки первой рассылки здесь появится очередь. Можно будет продолжить её, проверить результат и сохранить отчёт.");button("Создать рассылку",()->show(0),true);endPanel();return;}note("Все очереди сохраняют прогресс. Откройте нужную, чтобы продолжить или посмотреть сообщения.");for(int i=queues.length()-1;i>=0;i--){JSONObject task=queues.optJSONObject(i);accountRow(task.optString("title"),Channels.label(Store.channel(task))+" · "+Store.label(task.optString("state"))+"\n"+date(task.optLong("created")),()->taskView(task));}}
    String date(long value){return new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.getDefault()).format(new Date(value));}
    void taskView(JSONObject task){
        openedTask=task;shell(task.optString("title"),true);String channel=Store.channel(task);
        beginPanel("Ход отправки",Channels.label(channel));queueStateView=text("",17,ink);queueStateView.setTypeface(null,Typeface.BOLD);body.addView(queueStateView);queueCountsView=text("",14,muted);body.addView(queueCountsView);queueBar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);body.addView(queueBar,new LinearLayout.LayoutParams(-1,dp(12)));updateQueueHeader(task);
        boolean active=SendAccess.active()||BackgroundSender.active();if(active)button("Остановить очередь",()->{stopQueues();taskView(task);},true);
        else{Button start=button(Channels.background(channel)?"Запустить в фоне":"Начать / продолжить автоматически",()->startAuto(task),true);if(Store.next(task)<0){start.setEnabled(false);start.setAlpha(.45f);}}
        if(Channels.background(channel))note(Channels.bot(channel)?"После запуска можно свернуть приложение и пользоваться телефоном. В уведомлении будет кнопка остановки.":"Веб-очередь не открывает мессенджер поверх других приложений. Совместимость и устойчивость веб-сессии требуют проверки после входа.");
        else if(!active)button("Открыть следующего вручную",()->{ensureNoAuto();int i=Store.next(task);if(i<0)throw new IllegalArgumentException("Нет новых получателей");manual(task,task.optJSONArray("rows").optJSONObject(i));},false);
        endPanel();beginPanel("Сообщения","Нажмите на получателя, чтобы увидеть полный текст и действия.");EditText search=edit("Найти имя, адрес или текст","",false);JSONArray rows=task.optJSONArray("rows");List<JSONObject> filtered=new ArrayList<>();ListView list=new ListView(this);list.setDivider(null);body.addView(list,new LinearLayout.LayoutParams(-1,dp(420)));
        BaseAdapter adapter=new BaseAdapter(){public int getCount(){return filtered.size();}public Object getItem(int i){return filtered.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){JSONObject r=filtered.get(i);LinearLayout row=column();row.setPadding(dp(10),dp(8),dp(10),dp(10));TextView who=text((r.optString("name").isEmpty()?Store.target(r):r.optString("name")),16,ink);who.setTypeface(null,Typeface.BOLD);row.addView(who);row.addView(text(Store.target(r)+" · "+Store.label(r.optString("state")),13,accent));String message=r.optString("text");row.addView(text(message.length()>100?message.substring(0,100)+"…":message,14,muted));return row;}};queueAdapter=adapter;list.setAdapter(adapter);list.setOnItemClickListener((a,v,i,id)->guard(()->rowMenu(task,filtered.get(i))));
        Runnable update=()->{filtered.clear();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r.toString().toLowerCase(Locale.ROOT).contains(q))filtered.add(r);}adapter.notifyDataSetChanged();};search.addTextChangedListener(watcher(update));update.run();
        endPanel();quietAction("Сохранить отчёт CSV",()->export(report(task),"morcool-queue-report.csv","text/csv"));note("«Принято сервисом» и «Нажата отправка» не означают доставку или прочтение. Неопределённые результаты не повторяются автоматически.");
    }
    void updateQueueHeader(JSONObject task){JSONArray rows=task.optJSONArray("rows");int pending=0,busy=0,skipped=0,unknown=0;for(int i=0;i<rows.length();i++){String state=rows.optJSONObject(i).optString("state");if(state.equals("PENDING"))pending++;if(Arrays.asList("OPENED","SENDING_API","WEB_SENDING").contains(state))busy++;if(state.equals("SKIPPED"))skipped++;if(state.equals("UNKNOWN"))unknown++;}queueStateView.setText(Store.label(task.optString("state")));queueCountsView.setText("Обработано "+(rows.length()-pending-busy)+" из "+rows.length()+" · пропущено "+skipped+" · проверить "+unknown);queueBar.setMax(Math.max(1,rows.length()));queueBar.setProgress(rows.length()-pending-busy);if(queueAdapter!=null)queueAdapter.notifyDataSetChanged();}
    void stopQueues(){if(SendAccess.instance!=null)SendAccess.instance.pause("Остановлено пользователем");if(BackgroundSender.instance!=null)BackgroundSender.instance.pause("Остановлено пользователем");}

    void ensureNoAuto(){if(SendAccess.active()||BackgroundSender.active())throw new IllegalArgumentException("Сначала остановите текущую очередь");}
    void rowMenu(JSONObject task,JSONObject row){
        ensureNoAuto();String channel=Store.channel(task);List<String> actions=new ArrayList<>();if(channel.equals("whatsapp_app"))actions.add("Открыть в WhatsApp");actions.addAll(Arrays.asList("Я отправил(а) — отметить","Пропустить","Не писать этому адресату","Вернуть в очередь"));
        new AlertDialog.Builder(this).setTitle(row.optString("name").isEmpty()?Store.target(row):row.optString("name")).setMessage(row.optString("text")+"\n\n"+Store.label(row.optString("state"))+"\n"+row.optString("detail")).setPositiveButton("Действия",(d,n)->new AlertDialog.Builder(this).setItems(actions.toArray(new String[0]),(x,index)->guard(()->{ensureNoAuto();String action=actions.get(index);
            if(action.equals("Открыть в WhatsApp")){manual(task,row);return;}
            if(action.equals("Я отправил(а) — отметить"))Store.state(row,"MANUAL","Отправка отмечена вами; доставка не проверена");
            else if(action.equals("Пропустить"))Store.state(row,"SKIPPED","Пропущено вами");
            else if(action.equals("Не писать этому адресату")){Store.block(channel+":"+Store.target(row));Store.state(row,"SKIPPED","Стоп-лист");}
            else{new AlertDialog.Builder(this).setMessage("Если сообщение уже ушло, повтор создаст дубликат. Вернуть в очередь?").setPositiveButton("Вернуть",(a,b)->{Store.state(row,"PENDING","Возвращено вами");taskView(task);}).setNegativeButton("Отмена",null).show();return;}
            taskView(task);
        })).show()).setNegativeButton("Закрыть",null).show();
    }

    String whatsapp(){return Store.setting("whatsapp","com.whatsapp");}
    void installed(){try{getPackageManager().getPackageInfo(whatsapp(),0);}catch(Exception e){throw new IllegalArgumentException("Выбранное приложение WhatsApp не установлено. Измените вариант в настройках.");}}
    void manual(JSONObject t,JSONObject r){ensureNoAuto();installed();if(Store.blocked(r.optString("phone")))throw new IllegalArgumentException("Номер в стоп-листе");String s=r.optString("state");if(!s.equals("PENDING")){new AlertDialog.Builder(this).setMessage("Сообщение уже открывалось или обрабатывалось. Проверьте чат, чтобы не отправить повторно.").setPositiveButton("Открыть",(d,n)->openManual(t,r)).setNegativeButton("Отмена",null).show();}else openManual(t,r);}
    void openManual(JSONObject t,JSONObject r){guard(()->{Store.state(r,"OPENED","Открыто пользователем; результат нужно отметить вручную");startActivity(SendAccess.chatIntent(whatsapp(),r.optString("phone"),r.optString("text")));});}
    void startAuto(JSONObject task){
        ensureNoAuto();if(Channels.background(Store.channel(task))){startBackground(task);return;}installed();if(Store.next(task)<0)throw new IllegalArgumentException("Нет сообщений в очереди. Неопределённые результаты нужно проверить вручную.");
        AccessState.State access=SendAccess.connectionState(this);
        if(access==AccessState.State.DISABLED){new AlertDialog.Builder(this).setTitle("Разрешить автоотправку").setMessage("Включите «Morcool Sender — автоотправка» в специальных возможностях Android. Служба будет проверять поле сообщения и нажимать отправку в WhatsApp только после вашего запуска рассылки. Переписка не сохраняется и не отправляется на сервер. Затем вернитесь сюда.").setPositiveButton("Открыть настройки",(d,n)->openAccessSettings()).setNegativeButton("Отмена",null).show();return;}
        if(access==AccessState.State.CONNECTING){waitForAccess(task);return;}
        confirmAuto(task);
    }
    void openAccessSettings(){startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}
    void waitForAccess(JSONObject task){
        AlertDialog waiting=new AlertDialog.Builder(this).setTitle("Разрешение уже выдано").setMessage("Ожидаем подключение службы Android…").setNegativeButton("Отмена",null).create();waiting.show();long until=android.os.SystemClock.uptimeMillis()+3000;
        handler.post(new Runnable(){public void run(){if(isFinishing()||isDestroyed()||!waiting.isShowing())return;
            AccessState.State s=SendAccess.connectionState(MainActivity.this);
            if(s==AccessState.State.READY){waiting.dismiss();guard(()->startAuto(task));return;}
            if(s==AccessState.State.DISABLED){waiting.dismiss();guard(()->startAuto(task));return;}
            if(android.os.SystemClock.uptimeMillis()<until){handler.postDelayed(this,250);return;}
            waiting.dismiss();new AlertDialog.Builder(MainActivity.this).setTitle("Служба не подключена").setMessage("Разрешение специальных возможностей уже выдано. Android остановил или ещё не подключил службу. В настройках выключите и снова включите только «Morcool Sender — автоотправка», затем вернитесь в очередь. Повторно выдавать доступ к контактам не нужно.").setPositiveButton("Переподключить службу",(d,n)->openAccessSettings()).setNegativeButton("Отмена",null).show();
        }});
    }
    void confirmAuto(JSONObject task){
        if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},33);info("Разрешите уведомления для кнопки остановки и снова нажмите запуск.");return;}
        int seconds=Integer.parseInt(Store.setting("delay","0"));new AlertDialog.Builder(this).setTitle("Запустить отправку?").setMessage("Будут отправлены сообщения из этой очереди через "+(whatsapp().endsWith("w4b")?"WhatsApp Business":"WhatsApp")+". Интервал: "+seconds+" с. Держите телефон разблокированным и WhatsApp открытым. Получатели и тексты показаны ниже. Отсутствующие номера и ненайденные чаты пропускаются. Отменить можно кнопкой в уведомлении.").setPositiveButton("Начать отправку",(d,n)->guard(()->{ensureNoAuto();SendAccess service=SendAccess.instance;if(service==null){info(AccessState.description(SendAccess.connectionState(this)));return;}service.start(task,whatsapp(),seconds);})).setNegativeButton("Отмена",null).show();
    }
    void startBackground(JSONObject task){
        String channel=Store.channel(task);if(Store.next(task)<0)throw new IllegalArgumentException("Нет новых получателей. Неопределённые результаты проверяются вручную.");
        if(Channels.bot(channel)&&!Secrets.has(this,channel)){new AlertDialog.Builder(this).setMessage("Сначала добавьте токен "+Channels.label(channel)+" в разделе «Аккаунты».").setPositiveButton("Подключить",(d,n)->{page=3;botAccount(channel);}).setNegativeButton("Отмена",null).show();return;}
        if(Channels.web(channel)&&!Store.setting("session_"+channel,"").equals("Веб-вход выполнен")){new AlertDialog.Builder(this).setMessage("Сначала войдите в личный аккаунт. Для веб-режима потребуется проверить работу после входа.").setPositiveButton("Войти",(d,n)->startActivity(new Intent(this,WebAccountActivity.class).putExtra("channel",channel))).setNegativeButton("Отмена",null).show();return;}
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},33);info("Разрешите уведомления для остановки фоновой очереди, затем повторите запуск.");return;}
        new AlertDialog.Builder(this).setTitle("Запустить фоновую очередь?").setMessage(Channels.label(channel)+"\nГотовые сообщения показаны в очереди. После запуска можно пользоваться телефоном. Остановка доступна в уведомлении.").setPositiveButton("Запустить",(d,n)->guard(()->{ensureNoAuto();BackgroundSender.launch(this,task.optString("id"));handler.postDelayed(()->{if(!isFinishing()&&openedTask==task)taskView(task);},500);})).setNegativeButton("Отмена",null).show();
    }
    void accounts(){
        note("Подключите нужный способ один раз. Затем выберите его при создании рассылки.");
        accountRow("WhatsApp","Личный веб-аккаунт: "+Store.setting("session_whatsapp_web","не подключён")+"\nНа экране: "+(SendAccess.connectionState(this)==AccessState.State.READY?"служба подключена":"нужно настроить службу"),()->accountOptions("WhatsApp","whatsapp_web",null));
        accountRow("Telegram","Личный аккаунт: "+Store.setting("session_telegram_web","не подключён")+"\nБот: "+(Secrets.has(this,"telegram_bot")?"токен сохранён":"не подключён"),()->accountOptions("Telegram","telegram_web","telegram_bot"));
        accountRow("MAX","Личный аккаунт: "+Store.setting("session_max_web","не подключён")+"\nБот: "+(Secrets.has(this,"max_bot")?"токен сохранён":"не подключён"),()->accountOptions("MAX","max_web","max_bot"));
        beginPanel("Как выбрать способ","Личный аккаунт подключается через официальную веб-страницу. Этот режим экспериментальный: совместимость нужно проверить после входа.");note("Боты работают в фоне и отправляют по Chat ID. У каждого мессенджера свои условия доступа к получателю.");endPanel();
        accountRow("Настройки приложения","Интервал, стоп-лист, экспорт и резервные копии",this::dataSettings);
        quietAction("Выйти из всех личных веб-аккаунтов",()->{ensureNoAuto();new AlertDialog.Builder(this).setTitle("Завершить веб-вход?").setMessage("В этом приложении будут завершены личные веб-сессии WhatsApp, Telegram и MAX. Установленные мессенджеры продолжат работать.").setPositiveButton("Выйти",(d,n)->{WebSessions.clearAll();show(3);}).setNegativeButton("Оставить",null).show();});
    }
    void accountOptions(String name,String web,String bot){String[] choices=bot==null?new String[]{"Личный аккаунт — веб-вход","WhatsApp на экране — настройка службы"}:new String[]{"Личный аккаунт — веб-вход","Бот — подключить токен"};new AlertDialog.Builder(this).setTitle(name).setItems(choices,(d,n)->guard(()->{ensureNoAuto();if(n==0)startActivity(new Intent(this,WebAccountActivity.class).putExtra("channel",web));else if(bot==null)openAccessSettings();else botAccount(bot);})).show();}
    void accountRow(String title,String subtitle,Runnable action){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(13),dp(12),dp(13));row.setMinimumHeight(dp(82));row.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x2217633e),rounded(surface,16),null));LinearLayout words=column();TextView t=text(title,17,ink);t.setTypeface(null,Typeface.BOLD);words.addView(t);words.addView(text(subtitle,13,muted));row.addView(words,new LinearLayout.LayoutParams(0,-2,1));UiIcon arrow=new UiIcon(this,4,accent);arrow.setRotation(270);row.addView(arrow,new LinearLayout.LayoutParams(dp(22),dp(22)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);body.addView(row,p);row.setOnClickListener(v->guard(action));}
    void botAccount(String channel){
        shell(Channels.label(channel),true);beginPanel("Подключение бота","");note("Токен будет зашифрован средствами Android и не попадёт в экспорт контактов или JSON-копию.");label("Токен бота");EditText token=edit("Вставьте токен","",false);token.setInputType(129);note(Secrets.has(this,channel)?"Токен уже сохранён. Пустое поле не изменяет его.":"Получите токен при создании бота. Для Telegram — у BotFather, для MAX — на платформе MAX для партнёров.");
        sticky(button("Сохранить токен",()->{ensureNoAuto();if(token.getText().toString().trim().isEmpty())throw new IllegalArgumentException("Вставьте токен");Secrets.set(this,channel,token.getText().toString());show(3);info("Токен сохранён. Доступ проверится при запуске очереди.");},true));endPanel();
        if(Secrets.has(this,channel))button("Удалить токен",()->{ensureNoAuto();new AlertDialog.Builder(this).setMessage("Удалить сохранённый токен?").setPositiveButton("Удалить",(d,n)->{Secrets.set(this,channel,"");show(3);}).setNegativeButton("Отмена",null).show();},false);
    }
    void dataSettings(){
        shell("Настройки",true);beginPanel("Темп отправки","Дополнительная пауза между получателями. Ограничения сервиса сохраняются.");label("Пауза между сообщениями, секунды");EditText delay=edit("0 — без дополнительной паузы",Store.setting("delay","0"),false);delay.setInputType(2);note("Сервис может установить собственное время ожидания. Очередь его учтёт.");button("Сохранить интервал",()->{saveInterval(delay);info("Интервал сохранён");},false);endPanel();
        beginDisclosure("Фоновая очередь","Ожидание сервиса, недоступные адреса и время поиска");note("Эти параметры действуют для ботов и личных веб-аккаунтов.");label("Если сервис просит подождать");Spinner rate=spinner(Arrays.asList("Подождать и продолжить","Остановить очередь"),Store.setting("api_rate_limit_policy","wait").equals("pause")?1:0);label("Если адресат недоступен");Spinner unavailable=spinner(Arrays.asList("Пропустить и идти дальше","Остановиться для проверки"),Store.setting("unavailable_policy","skip").equals("pause")?1:0);label("Время поиска веб-чата, секунды");EditText timeout=edit("От 15 до 180 секунд",Store.setting("web_prepare_timeout_seconds","60"),false);timeout.setInputType(2);note("Если результат отправки неизвестен, очередь остановится в любом случае: сначала нужно проверить чат, чтобы не создать повтор.");button("Сохранить параметры очереди",()->{int seconds;try{seconds=Integer.parseInt(timeout.getText().toString().trim());}catch(Exception e){throw new IllegalArgumentException("Укажите время поиска целым числом от 15 до 180 секунд");}if(seconds<15||seconds>180)throw new IllegalArgumentException("Время поиска может быть от 15 до 180 секунд");Store.set("web_prepare_timeout_seconds",Integer.toString(seconds));Store.set("api_rate_limit_policy",rate.getSelectedItemPosition()==0?"wait":"pause");Store.set("unavailable_policy",unavailable.getSelectedItemPosition()==0?"skip":"pause");info("Параметры очереди сохранены");},false);endPanel();
        beginDisclosure("Номера и страна","Код для номеров без международного префикса");EditText country=edit("Например: 7",Store.setting("country","7"),false);country.setInputType(3);button("Сохранить код страны",()->{String value=country.getText().toString().replaceAll("[^0-9]","");if(!value.matches("[1-9][0-9]{0,3}"))throw new IllegalArgumentException("Укажите код страны цифрами, например 7");Store.set("country",value);info("Код страны сохранён");},false);endPanel();
        beginDisclosure("WhatsApp на экране","Выбор приложения и подключение службы");Spinner app=spinner(Arrays.asList("WhatsApp","WhatsApp Business"),whatsapp().endsWith("w4b")?1:0);app.setOnItemSelectedListener(new SimpleSelected(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){Store.set("whatsapp",pos==0?"com.whatsapp":"com.whatsapp.w4b");}});accessStatus=text(AccessState.description(SendAccess.connectionState(this)),14,muted);body.addView(accessStatus);button("Открыть специальные возможности",this::openAccessSettings,false);endPanel();
        accountRow("Стоп-лист",Store.list("blocked").length()+" адресов · исключены из будущей отправки",this::blockedScreen);
        beginDisclosure("Резервные копии и данные","Сохранить историю или восстановить копию");note("Контакты, тексты и история хранятся на устройстве. Токены и веб-вход не включаются в JSON-копию.");button("Сохранить резервную копию",()->export(Store.backup(),"morcool-sender-backup.json","application/json"),false);button("Восстановить из копии",()->{ensureNoAuto();pick(12,"*/*");},false);quietAction("Экспортировать контакты в CSV",()->export(contactsCsv(),"morcool-contacts.csv","text/csv"));endPanel();
        note("Morcool Sender · "+appVersion()+"\nБесплатно, без рекламы и подписки. Личные веб-режимы требуют проверки после входа. Приложение не связано с владельцами мессенджеров.");
    }
    String appVersion(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "preview";}}
    void blockedScreen(){shell("Стоп-лист",true);detailBack=this::dataSettings;beginPanel("Кому больше не писать","Эти адреса проверяются при создании очереди и перед каждым получателем.");button("Добавить номер телефона",()->{EditText field=new EditText(this);field.setInputType(3);field.setHint("+7…");new AlertDialog.Builder(this).setTitle("Добавить в стоп-лист").setView(field).setPositiveButton("Добавить",(d,n)->guard(()->{Store.block(Core.phone(field.getText().toString(),Store.setting("country","7")));blockedScreen();})).setNegativeButton("Отмена",null).show();},false);endPanel();JSONArray blocked=Store.list("blocked");if(blocked.length()==0)note("Стоп-лист пока пуст. Адрес также можно заблокировать из карточки контакта или очереди.");for(int i=0;i<blocked.length();i++){String address=blocked.optString(i);accountRow(blockedLabel(address),"Нажмите, чтобы убрать из стоп-листа",()->new AlertDialog.Builder(this).setMessage("Снова разрешить отправку на этот адрес?").setPositiveButton("Разрешить",(d,n)->{Store.unblock(address);blockedScreen();}).setNegativeButton("Оставить",null).show());}}
    String blockedLabel(String value){int split=value.indexOf(':');if(split>0)try{return Channels.label(value.substring(0,split))+" · "+value.substring(split+1);}catch(Exception ignored){}return value;}
    static class SimpleSelected implements AdapterView.OnItemSelectedListener{public void onItemSelected(AdapterView<?> p,View v,int pos,long id){}public void onNothingSelected(AdapterView<?> p){}}
    String contactsCsv(){String[] keys={"phone","name","group","note","telegram","max","telegram_chat_id","max_chat_id","max_user_id","fields_json"};StringBuilder out=new StringBuilder("\uFEFF"+TextUtils.join(",",keys)+"\r\n");JSONArray contacts=Store.list("contacts");for(int i=0;i<contacts.length();i++){JSONObject c=contacts.optJSONObject(i);Map<String,String> fields=Store.fields(c);for(int k=0;k<keys.length;k++){if(k>0)out.append(',');String key=keys[k];String value=key.equals("fields_json")?(c.optJSONObject("fields")==null?"{}":c.optJSONObject("fields").toString()):c.has(key)?c.optString(key):fields.containsKey(key)?fields.get(key):"";out.append(Core.quote(value));}out.append("\r\n");}return out.toString();}
    String report(JSONObject task){StringBuilder b=new StringBuilder("\uFEFFchannel,target,phone,name,status,detail,time,message_id,text\r\n");JSONArray a=task.optJSONArray("rows");for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);String[] values={Channels.label(Store.channel(task)),Store.target(r),r.optString("phone"),r.optString("name"),Store.label(r.optString("state")),r.optString("detail"),r.optLong("time")==0?"":date(r.optLong("time")),r.optString("message_id"),r.optString("text")};for(int k=0;k<values.length;k++){if(k>0)b.append(',');b.append(Core.quote(values[k]));}b.append("\r\n");}return b.toString();}

    void export(String value,String name,String mime){exportText=value;exportMime=mime;exportBackup=mime.equals("application/json");Store.set("pending_export",value);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,11);}
    byte[] read(Uri uri)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>10*1024*1024)throw new IOException("Файл больше 10 МБ. Разделите его на части.");out.write(buf,0,n);}return out.toByteArray();}}
    String decode(byte[] b){try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();}catch(Exception e){return new String(b,Charset.forName("windows-1251"));}}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();
        if(request==13){guard(()->{try(Cursor c=getContentResolver().query(uri,new String[]{ContactsContract.CommonDataKinds.Phone.NUMBER,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())editContact(Store.object("phone",c.getString(0),"name",c.getString(1),"group",draftGroup.isEmpty()?"Контакты":draftGroup));} });return;}
        if(request==11){new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){out.write(Store.setting("pending_export",exportText).getBytes(StandardCharsets.UTF_8));runOnUiThread(()->{Store.set("pending_export","");info("Файл сохранён");});}catch(Exception e){runOnUiThread(()->error(e.getMessage()));}}).start();return;}
        shell("Читаем файл…",true);note("Большие таблицы обрабатываются в фоне.");new Thread(()->{try{byte[] bytes=read(uri);
            if(request==12){String raw=decode(bytes);new JSONObject(raw);runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Заменить данные приложения?").setMessage("Контакты, шаблоны, стоп-лист и история будут заменены данными из копии. Сначала сохраните текущую копию, если она нужна.").setPositiveButton("Восстановить",(d,n)->guard(()->{try{ensureNoAuto();Store.restore(raw);draftTitle=Store.setting("draft_title","");draftMessage=Store.setting("draft_message","Здравствуйте, {name}!");draftGroup=Store.setting("draft_group","");show(3);info("Копия восстановлена. Автоотправка не запущена.");}catch(Exception e){throw new IllegalArgumentException(e.getMessage());}})).setNegativeButton("Отмена",(d,n)->show(3)).show());}
            else if(bytes.length>=2&&bytes[0]=='P'&&bytes[1]=='K'){Sheets.Book book=Sheets.read(bytes);runOnUiThread(()->{if(book.names.size()==1)mapping(book.sheets.get(0),book.names.get(0));else new AlertDialog.Builder(this).setTitle("Выберите лист Excel").setItems(book.names.toArray(new String[0]),(d,n)->guard(()->mapping(book.sheets.get(n),book.names.get(n)))).setOnCancelListener(d->show(1)).show();});}
            else{List<List<String>> rows=Core.csv(decode(bytes));runOnUiThread(()->guard(()->mapping(rows,"Контакты")));}
        }catch(Exception e){runOnUiThread(()->{show(request==12?3:1);error("Не удалось прочитать файл: "+e.getMessage());});}}).start();
    }
